/**
 * Main persona command - manages agent persona.
 *
 * Supports both interactive and non-interactive modes:
 * - Interactive: prompts for environment and action selection
 * - Non-interactive (production): use env + action with optional flags
 */
export async function personaCommand(env, action, cmdObj) {
    return withErrorHandling(async () => {
        const options = {
            personaVersion: cmdObj?.personaVersion || null,
            force: cmdObj?.force || false,
        };
        // Initialize command (validates config + auth)
        const { agentId, apiKey } = await initializeCommand();
        let selectedEnvironment;
        // Check if environment was provided as argument
        if (env) {
            const normalizedEnv = validateOrSuggest('persona.env', env);
            selectedEnvironment = normalizedEnv === 'staging' ? 'sandbox' : normalizedEnv;
        }
        else {
            // Step 4: Prompt for environment selection
            const envAnswer = await safePrompt([
                {
                    type: 'list',
                    name: 'environment',
                    message: 'Select environment:',
                    choices: [
                        { name: '🔧 Sandbox (edit and test)', value: 'sandbox' },
                        { name: '🚀 Production (view and deploy versions)', value: 'production' }
                    ]
                }
            ]);
            if (!envAnswer)
                return;
            selectedEnvironment = envAnswer.environment;
        }
        const context = {
            environment: selectedEnvironment,
            agentId,
            apiKey,
        };
        // Step 5: Handle based on environment and action
        if (selectedEnvironment === 'sandbox') {
            if (action === 'view') {
                // Non-interactive: display persona and exit
                const currentPersona = getAgentPersona() ?? '';
                if (currentPersona.trim()) {
                    console.log(currentPersona);
                }
                else {
                    console.log('ℹ️  No persona configured.');
                }
                return;
            }
            // Other sandbox actions are interactive (editing requires editor)
            await manageSandboxPersonaInteractive(context);
        }
        else {
            // Production mode supports non-interactive actions
            if (action) {
                await executeProductionNonInteractive(context, action, options);
            }
            else {
                await manageProductionPersonaInteractive(context);
            }
        }
        trackEvent('cli_persona_action', {
            environment: selectedEnvironment,
            action: action || null,
            non_interactive: !!env,
            force_mode: options.force || false,
        });
    }, "persona");
}
// ─────────────────────────────────────────────────────────────────────────────
// Shared Core Functions
