// Interactive Mode (Sandbox)
// ─────────────────────────────────────────────────────────────────────────────
async function manageSandboxPersonaInteractive(context) {
    let continueManaging = true;
    while (continueManaging) {
        const currentPersona = getAgentPersona() ?? '';
        console.log("\n" + "=".repeat(60));
        console.log("🌙 Sandbox Persona Management");
        console.log("=".repeat(60) + "\n");
        if (currentPersona && currentPersona.trim()) {
            const preview = currentPersona.length > 100
                ? currentPersona.substring(0, 100) + '...'
                : currentPersona;
            console.log("Current persona:");
            console.log(preview);
            console.log();
        }
        else {
            console.log("ℹ️  No persona configured.\n");
        }
        const actionAnswer = await safePrompt([
            {
                type: 'list',
                name: 'action',
                message: 'What would you like to do?',
                choices: [
                    { name: '👁️  View full persona', value: 'view' },
                    { name: '✏️  Edit persona', value: 'edit' },
                    { name: '📦 Create version (push to production)', value: 'create_version' },
                    { name: '📋 List versions', value: 'list_versions' },
                    { name: '❌ Exit', value: 'exit' }
                ]
            }
        ]);
        if (!actionAnswer)
            return;
        const { action } = actionAnswer;
        switch (action) {
            case 'view':
                await viewPersonaInteractive(currentPersona);
                break;
            case 'edit':
                await editSandboxPersonaInteractive(context, currentPersona);
                break;
            case 'create_version':
                await createPersonaVersionInteractive(context, currentPersona);
                break;
            case 'list_versions':
                await listPersonaVersionsInteractive(context);
                break;
            case 'exit':
                continueManaging = false;
                console.log("\n👋 Goodbye!\n");
                break;
        }
    }
}
async function viewPersonaInteractive(persona) {
    console.log("\n" + "=".repeat(60));
    console.log("Agent Persona");
    console.log("=".repeat(60));
    if (persona && persona.trim()) {
        console.log(persona);
    }
    else {
        console.log("No persona configured.");
    }
    console.log("=".repeat(60) + "\n");
    await inquirer.prompt([
        {
            type: 'input',
            name: 'continue',
            message: 'Press Enter to continue...'
        }
    ]);
}
async function editSandboxPersonaInteractive(context, currentPersona) {
    const defaultPersona = currentPersona || `# Write your agent persona here
# 
# Example:
# You are a helpful customer service assistant for [Your Company].
# You help users with product inquiries and order management.
# You are friendly, professional, and knowledgeable.`;
    const personaAnswer = await safePrompt([
        {
            type: 'editor',
            name: 'newPersona',
            message: 'Edit persona (will open in your default editor):',
            default: defaultPersona,
            validate: (input) => {
                if (!input.trim()) {
                    return 'Persona cannot be empty';
                }
                const withoutComments = input.split('\n')
                    .filter((line) => !line.trim().startsWith('#'))
                    .join('\n')
                    .trim();
                if (!withoutComments) {
                    return 'Persona cannot be empty (only comments found)';
                }
                return true;
            }
        }
    ]);
    if (!personaAnswer)
        return;
    const { newPersona } = personaAnswer;
    const trimmedPersona = newPersona.trim();
    writeProgress("🔄 Saving persona to code (LuaAgent)...");
    const success = setAgentPersona(trimmedPersona);
    if (success) {
        writeSuccess("✅ Persona saved to code successfully");
    }
    else {
        console.error("❌ Failed to save persona to code");
    }
}
async function createPersonaVersionInteractive(context, currentPersona) {
    if (!currentPersona || !currentPersona.trim()) {
        console.log("\n❌ No persona to create version from. Please edit and save a persona first.\n");
        return;
    }
    console.log("\n⚠️  This will create a new persona version that can be deployed to production.");
    const confirmAnswer = await safePrompt([
        {
            type: 'confirm',
            name: 'confirm',
            message: 'Create new persona version?',
            default: true
        }
    ]);
    if (!confirmAnswer || !confirmAnswer.confirm) {
        console.log("\nℹ️  Version creation cancelled.\n");
        return;
    }
    writeProgress("🔄 Creating persona version...");
    try {
        const personaApi = new PersonaApi(BASE_URLS.API, context.apiKey, context.agentId);
        const response = await personaApi.createVersion(currentPersona);
        if (!response.success || !response.data) {
            throw new Error(response.error?.message || 'Failed to create persona version');
        }
        const versionNum = response.data.version || 'N/A';
        writeSuccess(`✅ Persona version created successfully (version: ${versionNum})`);
        writeInfo("💡 You can deploy this version from the production environment.");
    }
    catch (error) {
        console.error('❌ Error creating persona version:', error);
    }
}
async function listPersonaVersionsInteractive(context) {
    writeProgress("🔄 Loading persona versions...");
    const versions = await fetchVersionsCore(context);
    if (!versions || versions.length === 0) {
        console.log("\nℹ️  No persona versions found.\n");
        console.log("💡 Create a version first from sandbox mode.\n");
        return;
    }
    const versionAnswer = await safePrompt([
        {
            type: 'list',
            name: 'selectedVersionIndex',
            message: 'Select a persona version to view:',
            choices: versions.map((version, index) => {
                const date = new Date(version.createdDate);
                const dateStr = date.toLocaleDateString();
                const timeStr = date.toLocaleTimeString();
                const status = version.status === 'draft' ? '[DRAFT]' : '';
                const currentMark = version.isCurrent ? ' ⭐ CURRENT' : '';
                return {
                    name: `Version ${version.version} ${status} - (${dateStr}) ${timeStr} ${currentMark}`,
                    value: index
                };
            })
        }
    ]);
    if (!versionAnswer)
        return;
    await viewVersionDetailsInteractive(versions[versionAnswer.selectedVersionIndex]);
}
async function viewVersionDetailsInteractive(version) {
    const date = new Date(version.createdDate);
    console.log("\n" + "=".repeat(60));
    console.log(`Persona Version ${version.version}`);
    console.log("=".repeat(60));
    console.log(`Created: ${date.toLocaleString()}`);
    const versionStatus = version.status === 'draft' ? '🔨 DRAFT' : '';
    console.log(`Version Status: ${versionStatus}`);
    console.log(`Active Status: ${version.isCurrent ? '⭐ CURRENT' : 'Available'}`);
    if (version.createdBy) {
        console.log(`Created by: ${version.createdBy}`);
    }
    console.log("=".repeat(60) + "\n");
    console.log(version.persona);
    console.log("\n" + "=".repeat(60) + "\n");
    await inquirer.prompt([
        {
            type: 'input',
            name: 'continue',
            message: 'Press Enter to continue...'
        }
    ]);
}
